import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");

    private final OrderRepository repository = new OrderRepository();
    private final OrderService service = new OrderService(repository, Clock.fixed(NOW, ZoneOffset.UTC));

    @Test
    void cancelsPlacedOrdersOlderThanThirtyDays() {
        String old = service.place("c-1", Money.pln(1000), NOW.minusSeconds(31L * 24 * 3600));
        String recent = service.place("c-2", Money.pln(1000), NOW.minusSeconds(29L * 24 * 3600));

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", service.summary(old).status());
        assertEquals("PLACED", service.summary(recent).status());
    }

    @Test
    void anOrderExactlyThirtyDaysOldIsKept() {
        String id = service.place("c-1", Money.pln(1000), NOW.minusSeconds(30L * 24 * 3600));

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(id).status());
    }

    @Test
    void leavesOldOrdersThatAreNotPlaced() {
        String confirmed = service.place("c-1", Money.pln(1000), NOW.minusSeconds(40L * 24 * 3600));
        service.confirm(confirmed);
        String cancelled = service.place("c-2", Money.pln(1000), NOW.minusSeconds(40L * 24 * 3600));
        service.cancel(cancelled);

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", service.summary(confirmed).status());
        assertEquals("CANCELLED", service.summary(cancelled).status());
    }

    @Test
    void secondRunCancelsNothingMore() {
        service.place("c-1", Money.pln(1000), NOW.minusSeconds(45L * 24 * 3600));

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}
